BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_spec'
L=[['古希腊 lúein／lúō','解开、松开']]
A=L+[['古希腊 ana- + lúein → analýein → análusis','解开、分解 → 把复杂事物分开考察'],['中世纪拉丁 analysis → 英语 analysis','分析；分析的结果']]
AV=A[:-1]+[['中世纪拉丁 analysis','分解、分析'],['并列分析：英语 analysis 造动词；或经法语 analyse／analyser 借入','英语动词的形成路线有分歧，法语现存动词记录较晚'],['英语 analyse／analyze','分析、细察']]
AT=L+[['古希腊 analýein → analytós → analytikós','解开 → 已分解的 → 分析的'],['中世纪拉丁 analyticus','分析的']]
P=L+[['古希腊 para- + lúein → paralýein → parálusis','使失去力量、活动能力 → 麻痹'],['拉丁 paralysis','麻痹、瘫痪']]
PV=P+[['古法语 paralisie → 法语 paralyser','瘫痪 → 使瘫痪'],['英语 paralyze／paralyse','使失去活动能力；使系统停摆']]
C=L+[['古希腊 kata- + lúein → katalýein → katálusis','完全解开 → 解散、分解'],['拉丁化形式 catalysis → 英语 catalysis','早期指分解，后来采用化学催化义']]
CV=C+[['英语 catalyze／catalyse','很可能按 analysis／analyze 的对应方式从 catalysis 造动词，也可能受法语 catalyser 影响']]
W=[
E('analysis','/əˈnæləsɪs/','分析；分析报告或结果','把一团复杂的问题拆开，看看里面有什么、各部分怎样联系。','经中世纪拉丁 analysis，来自希腊 análusis。希腊 ana- 在这里有彻底、分开的作用，ly- 接“解开”；名词早于英语动词，不是 analyze 直接加 -sis。',A,'分析账单，可以看钱花在哪几类；分析文章，可以看观点怎样一步步建立。拆开是理解过程，不一定真的把物体弄碎。复数 analyses 读 /əˈnæləsiːz/。','an analysis of；data analysis；carry out an analysis；in the final analysis。','summary 把内容缩短；analysis 解释结构、关系或原因。只把数字抄在一起，还不等于完成了分析。',('Her analysis explains why customers leave after the first month.','她的分析解释了顾客为什么在第一个月后流失。'),('The report includes an analysis of the main characters.','报告包含对主要人物的分析。'),sources=['https://www.etymonline.com/word/analysis']),
E('analyze','/ˈænəlaɪz/','分析；细察','先把问题分成能检查的部分，再判断它怎样运作。','美国英语通常用 analyze，英国英语通常用 analyse。历史上既有法语 analyser 借入说，也有英语 analysis 造动词说；现存记载的先后不支持把法语路线当作唯一确定答案。',AV,'analyze a sample 是检查样本组成；analyze an argument 是看论据能否支持结论。两者都在问“里面是什么、彼此有什么关系”，不是凭第一印象下判断。','analyze data；analyze a sample；analyze the causes of。','examine 可以只是仔细查看；analyze 通常还要分出成分、规律或原因。analyze 与 analyse 不是深浅不同的两种分析。',('The team will analyze the survey results next week.','团队下周会分析调查结果。'),('We analyzed the argument sentence by sentence.','我们逐句分析了这套论证。'),sources=['https://www.etymonline.com/word/analyze']),
E('analyse','/ˈænəlaɪz/','分析；研究各部分的关系','面对一个整体，逐项检查，弄清楚它为什么是这样。','analyze 的主要英式拼写。它与 analysis 同族；英语从名词造动词与借法语 analyser 是两种词源分析，不能仅凭拼写确定唯一借入方向。',AV,'analyse the failure 不只说“失败了”，而要找哪个环节出了问题；analyse a poem 则看语言、结构和意象怎样共同起作用。过去式 analysed，进行式 analysing。','analyse the results；analyse a problem；analyse how something works。','describe 是把样子说出来；analyse 进一步解释组成与关系。英式 analyse 和美式 analyze 读音、核心意思相同。',('The students analysed how the advertisement creates a sense of urgency.','学生们分析了这则广告怎样制造紧迫感。'),('We need to analyse the costs before changing the plan.','修改计划前，我们需要分析成本。'),sources=['https://www.etymonline.com/word/analyze']),
E('analyst','/ˈænəlɪst/','分析员；分析师','把资料变成判断的人：不只收集数字，还说明数字意味着什么。','借法语 analyste，接 analyse／analyser 这一词族，远源是希腊 análusis。今天可以把 -ist 理解为从事者，但不必假设它最初由英语 analyze 加 -ist 造出。',A[:-1]+[['中世纪拉丁 analysis → 法语 analyse／analyste','分析 → 从事分析的人'],['英语 analyst','分析员、分析师']],'a financial analyst 研究财务或投资信息；a systems analyst 研究系统需要怎样工作。单说 analyst 时，具体分析什么要看上下文；心理治疗语境也可能指精神分析师。','a data analyst；a financial analyst；a political analyst。','researcher 强调开展研究；analyst 强调解释材料、发现规律并作判断，实际工作可以重叠。',('The analyst compared this year’s sales with last year’s figures.','分析师把今年的销售额与去年的数字作了比较。'),('A political analyst explained the possible effects of the vote.','一位政治分析人士解释了投票可能产生的影响。'),sources=['https://www.etymonline.com/word/analyst']),
E('analytical','/ˌænəˈlɪtɪkəl/','善于分析的；分析性的','不急着凭感觉下结论，而是把问题拆清楚、把依据接起来。','接中世纪拉丁 analyticus，再加英语 -al。现代可看成 analytic + -al，但 analytical 的英语记录更早，不能倒画成先有英语 analytic 才有它。',AT+[['中世纪拉丁 analyticus + 英语 -al → analytical','采用分析方法的；善于分析的']],'an analytical mind 善于辨认关系、追问原因；analytical skills 包括比较证据、检查假设。它说思考方式，并不表示这个人没有感情。','analytical skills；an analytical approach；analytical thinking。','critical 强调评估是否站得住；analytical 强调拆分和理清结构。严谨思考常常同时需要两者。',('The job requires strong analytical skills.','这份工作需要较强的分析能力。'),('Her analytical approach helped us find the source of the delay.','她采用的分析方法帮助我们找到了延误的原因。'),sources=['https://www.etymonline.com/word/analytical']),
E('analytic','/ˌænəˈlɪtɪk/','分析的；解析的','用分析来处理问题，或属于某一套分析方法。','经中世纪拉丁 analyticus 接希腊 analytikós，最终接 analýein“解开、分析”。这是学术借词路线，不是把英语 analysis 的词尾机械换成 -tic。',AT+[['英语 analytic','分析的；用于若干学科名称的分析、解析义']],'analytic approach 可以指分析式处理方法；analytic geometry 是用坐标、方程研究几何关系的解析几何。学科术语里的含义更具体，不能每次都只译成“会分析”。','an analytic approach；analytic geometry；analytic philosophy。','日常说一个人的思维或能力，analytical 更常见；analytic 常见于固定学术用语，两者并非处处不能互换。',('The course introduces analytic geometry through simple coordinate problems.','这门课通过简单的坐标问题介绍解析几何。'),('The paper takes an analytic approach to the debate.','论文采用分析的方法讨论这场争论。'),sources=['https://www.etymonline.com/word/analytic']),
E('analytically','/ˌænəˈlɪtɪkli/','以分析的方式；用解析方法','不是笼统地说“好像如此”，而是逐项检查后说明理由。','analytical + -ly；它修饰思考、处理或求解的方式，沿 analytical 的拉丁、希腊前史。',AT+[['中世纪拉丁 analyticus + -al → 英语 analytical','分析的'],['英语 analytical + -ly → analytically','以分析方式；用解析方法']],'think analytically 是有条理地分析；在数学语境，solve analytically 常指用公式和推导求解，而不是只让电脑算出近似数值。两种用法要随语境理解。','think analytically；approach something analytically；solve analytically。','logically 强调推理连贯；analytically 强调分解、辨认关系。两者常相辅相成。',('Try to approach the complaint analytically before responding.','回应投诉前，先试着有条理地分析问题。'),('This simple equation can be solved analytically.','这个简单方程可以用解析方法求解。'),sources=['https://www.etymonline.com/word/analytical','https://en.wiktionary.org/wiki/analytically#English']),
E('analytics','/ˌænəˈlɪtɪks/','数据分析；分析方法','从一堆记录里找规律，帮助判断哪里有效、哪里需要调整。','历史上借后期拉丁 Analytica，来自希腊 analytiká，原与亚里士多德的分析、逻辑著作名称相关。现代可联系 analytic + 学科式 -s，但并不是 analysis 的普通复数。',AT[:2]+[['希腊 analytiká → 后期拉丁 Analytica','分析、逻辑著作的名称'],['英语 analytics','早期分析方法 → 现代尤其指数据信息的系统分析']],'web analytics 可以看访问者怎样进入、浏览和离开网站；business analytics 帮助把经营记录变成判断。仪表盘显示数字只是起点，关键是解释这些数字。','data analytics；web analytics；business analytics；predictive analytics。','analysis 可指一次具体分析；analytics 常指一套持续分析数据的方法或工具。analysis 的复数是 analyses。',('We use web analytics to see where visitors leave the site.','我们用网站分析查看访客在哪些地方离开。'),('The company added an analytics dashboard for its sales team.','公司为销售团队增加了一个数据分析看板。'),sources=['https://www.merriam-webster.com/dictionary/analytics']),
E('reanalysis','/ˌriːəˈnæləsɪs/','重新分析；重新理解','材料可能没换，但换了问题、方法或假设，再看一遍。','re-“再次” + analysis；属于英语里直接形成的再分析名词。',A+[['英语 re- + analysis → reanalysis','对已有材料再次分析或作新的解释']],'a reanalysis of the data 可以用另一种统计方法检查旧结论；语言学里还可指使用者把一个词或句子的结构重新理解。不是把原报告重新排版。','a reanalysis of the data；a detailed reanalysis；require reanalysis。','replication 通常指重复研究以检验结果；reanalysis 可以只重新处理已有数据，不必重新开展整项实验。',('A reanalysis of the data revealed a calculation error.','重新分析数据后发现了一处计算错误。'),('The new evidence prompted a reanalysis of the case.','新证据促使人们重新分析这个案件。'),sources=['https://en.wiktionary.org/wiki/reanalysis#English']),
E('catalyst','/ˈkætəlɪst/','催化剂；促成变化的因素','有它介入，原来迟迟不动的变化更容易推进。','由 catalysis 参照 analyst 一类形式造出，英语名词 catalyst 晚于催化意义的 catalysis 和 catalytic。不能把整族都反推成 catalyst 加后缀。',C+[['英语 catalysis → catalyst','按 analyst 一类形式造名词：起催化作用的物质；促成变化的因素']],'化学催化剂加快反应，并在催化循环结束时再生，整体上不被反应消耗；这不表示每一步都完全不变。比喻 a catalyst for change 是让变化加速或发生的关键推动因素。','a catalyst for change；act as a catalyst；use a catalyst。','cause 泛指原因；catalyst 常强调已有条件下的推动作用。比喻用法不要求这个因素像化学催化剂一样被再生。',('The reaction proceeds faster when a catalyst is added.','加入催化剂后，反应进行得更快。'),('The public meeting became a catalyst for change.','这次公众会议成为推动改变的关键因素。'),sources=['https://www.etymonline.com/word/catalyst','https://publications.iupac.org/pac/1976/pdf/4601x0071.pdf']),
E('catalytic','/ˌkætəˈlɪtɪk/','催化的；起促进作用的','形容一种作用：它帮助变化发生得更快。','接拉丁化的希腊 katalytikós“有分解作用的”，属于 kata- + ly- 的词族。化学用法早于英语 catalyst，现代虽能联系 catalyst，也不能把历史画成后者加 -ic。',L+[['古希腊 katalýein → katalytikós','分解 → 能起分解作用的'],['拉丁化形式 → 英语 catalytic','采用为化学催化形容词；也用于比喻']],'catalytic activity 是催化活性；a catalytic role 是起推动作用。汽车 catalytic converter 利用催化反应减少某些有害尾气成分，不是把所有排放都消除。','catalytic activity；a catalytic converter；play a catalytic role。','catalyst 是起作用的物质或因素；catalytic 是描述这种作用的形容词。',('The study compares the catalytic activity of two materials.','研究比较了两种材料的催化活性。'),('The small grant played a catalytic role in the project’s development.','这笔小额资助对项目发展起了推动作用。'),sources=['https://www.etymonline.com/word/catalytic','https://publications.iupac.org/pac/1976/pdf/4601x0071.pdf']),
E('catalysis','/kəˈtæləsɪs/','催化作用','说的是“借助催化剂让反应加快”这个过程。','借拉丁化的希腊 katálusis，原义是分解、解散；十九世纪被用于化学催化。kata- + ly- 的古老字面义不能代替今天的化学定义。',C,'催化剂在过程中可以参与中间步骤，之后再生；因此少量物质也能持续起作用。catalysis 不是某一种药剂的名字，也不专指把大分子分成小分子。','enzyme catalysis；acid catalysis；a study of catalysis。','catalyst 指催化剂；catalysis 指催化作用。hydrolysis 是水参与的特定断键过程，可以被催化，但两者不等同。',('The course includes a chapter on enzyme catalysis.','课程包含一章酶催化的内容。'),('Researchers study catalysis to improve industrial reactions.','研究人员研究催化作用，以改进工业反应。'),sources=['https://www.etymonline.com/word/catalysis','https://publications.iupac.org/pac/1976/pdf/4601x0071.pdf']),
E('catalyze','/ˈkætəlaɪz/','催化；促成；加速变化','让某个反应或转变更快发生。','很可能由 catalysis 参照 analysis／analyze 逆构成动词，并可能受法语 catalyser 影响。不是 catalyst 去掉 -st 再加 -ze。',CV,'an enzyme catalyzes a reaction 是酶催化反应；a new idea catalyzes change 是新想法推动改变。第二种说法借用化学的推动感，不是说社会变化真的发生了同一种反应。','catalyze a reaction；catalyze change；catalyze growth。','accelerate 直接说加快；catalyze 通常突出某个因素介入，带动原有过程或变化。英式常拼 catalyse。',('The enzyme catalyzes the breakdown of starch.','这种酶催化淀粉的分解。'),('The discussion helped catalyze a change in policy.','这次讨论有助于推动政策改变。'),sources=['https://www.etymonline.com/word/catalyze']),
E('catalyse','/ˈkætəlaɪz/','催化；促使变化发生','起推动作用，让变化越过原来的停滞点。','catalyze 的主要英式拼写；同样接 catalysis，可能按分析名词与动词的对应形式造词，也可能受法语 catalyser 影响。',CV,'catalyse a reaction 是技术用法；catalyse investment 或 catalyse reform 常见于政策、商业论述。它的语气比 help 更正式，也更强调带动变化。','catalyse a reaction；catalyse reform；catalyse innovation。','catalyse 与 catalyze 是拼写变体；英式过去式 catalysed、现在分词 catalysing，不改变核心含义。',('The metal can catalyse the reaction under these conditions.','在这些条件下，这种金属可以催化该反应。'),('The new partnership may catalyse further research.','新的合作关系可能带动进一步研究。'),sources=['https://www.etymonline.com/word/catalyze','https://www.collinsdictionary.com/dictionary/english/catalyse']),
E('paralysis','/pəˈræləsɪs/','瘫痪；麻痹；无法行动的状态','身体某部分动不了，或整个决策、组织过程卡住了。','经拉丁 paralysis 借希腊 parálusis，来自 para- + lúein 形成的 paralýein“使失去力量”。这种古老的“松解失能”联想不能当作现代医学病因解释。',P+[['英语 paralysis','肌肉活动能力丧失；比喻无法行动的状态']],'医学上可以是身体某部分失去自主运动能力，不一定全身都不能动。decision paralysis 则是选择越想越多，最后一个也做不了。','partial paralysis；facial paralysis；political paralysis；decision paralysis。','paralysis 强调活动或行动能力受阻；numbness 是麻木、感觉减弱，两者可能同时出现，但不是同一个意思。',('The injury caused paralysis in one leg.','这次损伤导致一条腿瘫痪。'),('Too many conflicting rules led to decision paralysis.','相互冲突的规则太多，导致人们迟迟无法作出决定。'),sources=['https://www.etymonline.com/word/paralysis','https://www.nhs.uk/conditions/paralysis/']),
E('paralyze','/ˈpærəlaɪz/','使瘫痪；使无法行动；使停摆','把本来能够行动的人或系统卡到动不了。','经法语 paralyser，接古法语 paralisie，最终来自拉丁 paralysis、希腊 parálusis。现代与英语 paralysis 对应，但历史中介是法语动词，不宜只写英语名词换词尾。',PV,'paralyze a limb 说肢体失去运动能力；paralyze transport 说交通大面积停摆。fear can paralyze someone 是怕到做不出动作或决定，不自动表示医学损伤。','paralyze a limb；paralyze the transport system；be paralyzed by fear。','immobilize 可以是把东西固定住；paralyze 更强调功能或行动能力失效。它比 delay 的“延误”程度强。',('The injury could paralyze the affected muscles.','这次损伤可能使受影响的肌肉瘫痪。'),('A major power failure can paralyze a city’s transport system.','一次大规模停电可能使城市交通系统陷入瘫痪。'),sources=['https://www.etymonline.com/word/paralyze','https://www.oxfordlearnersdictionaries.com/definition/english/paralyze']),
E('paralyse','/ˈpærəlaɪz/','使瘫痪；使无法行动','让活动、工作或决策失去推进能力。','paralyze 的主要英式拼写，来自法语 paralyser，远源接希腊“使失去力量”的 paralýein。不是 para-“旁边”加英语 lyse 就能直接推出全部现代意思。',PV,'a strike paralyses services 表示服务难以运作；anxiety paralyses someone 可以说焦虑使人迈不出下一步。语气很强，普通短暂拖延通常不需要这个词。','paralyse services；paralyse an economy；paralyse someone with fear。','paralyse 是动作，paralysis 是状态。英式第三人称 paralyses，和名词 paralysis 的复数形式同形时要看句法。',('The dispute threatened to paralyse the organisation.','这场争执可能使组织陷入停摆。'),('Fear of making a mistake can paralyse a new team leader.','怕犯错可能让新任团队负责人不敢采取行动。'),sources=['https://www.etymonline.com/word/paralyze','https://www.oxfordlearnersdictionaries.com/definition/english/paralyse']),
E('paralyzed','/ˈpærəlaɪzd/','瘫痪的；无法行动的；陷于停顿的','形容已经动不了，或一时无法采取行动的状态。','现代形式是 paralyze + -ed，也可直接作过去式。-ed 在这里读 /d/，不另加一个音节；前史沿法语 paralyser。',PV+[['现代英语 paralyze + -ed → paralyzed','受到影响而不能行动；过去式与分词形容词']],'a paralyzed arm 是失去运动能力的手臂；paralyzed by indecision 是犹豫到无从行动。形容人时只说明相关状态，不等于概括这个人的全部能力。','be paralyzed from the waist down；paralyzed by fear；a paralyzed system。','paralyzing 侧重使别人无法行动的作用；paralyzed 侧重受到影响后的状态。英式常写 paralysed。',('His left arm was paralyzed after the injury.','受伤后，他的左臂瘫痪了。'),('The committee was paralyzed by indecision.','委员会因犹豫不决而无法推进工作。'),sources=['https://www.etymonline.com/word/paralyze','https://www.oxfordlearnersdictionaries.com/definition/english/paralyzed']),
E('paralysed','/ˈpærəlaɪzd/','瘫痪的；动弹不得的；停摆的','原来能活动或处理事情，现在失去了这种能力。','英式 paralyse + -ed，对应美式 paralyzed。它既能构成被动语态，也能单独形容一种状态。',PV+[['现代英语 paralyse + -ed → paralysed','已失去活动或运作能力的']],'remain paralysed 强调这种状态持续；paralysed with fear 是吓得动不了。具体是身体功能问题、瞬间恐惧还是系统停顿，要由后面的情境判断。','remain paralysed；paralysed with fear；partially paralysed。','frozen 也能形容突然僵住；paralysed 更突出无法行动。它不一定表示字面结冰或永久失能。',('She stood paralysed with fear as the roof began to fall.','屋顶开始坍塌时，她吓得站在原地动弹不得。'),('The transport network remained paralysed throughout the morning.','整个上午，交通网一直处于瘫痪状态。'),sources=['https://www.etymonline.com/word/paralyze','https://www.collinsdictionary.com/dictionary/english/paralysed']),
E('paralytic','/ˌpærəˈlɪtɪk/','瘫痪的；使人无法动弹的；烂醉的〔英式口语〕','正式语境说活动能力受阻；英国口语里又夸张地说醉得不行。','经古法语 paralytique、拉丁 paralyticus，接希腊 paralytikós。形容词有自己的借入路线，不是英语 paralysis 简单换尾才出现。',L+[['古希腊 paralýein → paralytikós → 拉丁 paralyticus','使失去活动能力 → 与瘫痪有关的'],['古法语 paralytique → 英语 paralytic','瘫痪的；后来口语夸张指醉得不行']],'paralytic fear 是恐惧强到让人动不了；be paralytic 在英国非正式表达中可指烂醉。后一个意思是夸张说法，不能据此推断发生了医学瘫痪。','paralytic fear；a paralytic illness；get completely paralytic〔英式口语〕。','paralyzed 常描述结果状态；paralytic 可描述相关疾病或使人僵住的恐惧。说烂醉时通常放在 be／get 后。',('A paralytic fear kept him from opening the door.','强烈的恐惧让他不敢动手开门。'),('In the story, he gets paralytic at the wedding.','在这个故事里，他在婚礼上喝得烂醉。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/paralytic']),
E('palsy','/ˈpɔːlzi/','麻痹；瘫痪〔多见于疾病名称〕','常出现在特定病名里，涉及肌肉力量、控制或运动方面的问题。','与 paralysis 同源，但沿盎格鲁诺曼语 paralisie／parleisie、中古英语 palesie 进入英语，形式大幅缩短。不是现代英语把 paralysis 随手简称为 palsy。',P+[['盎格鲁诺曼语 paralisie／parleisie → 中古英语 palesie','麻痹、瘫痪'],['英语 palsy','保留在多种医学名称中']],'cerebral palsy 是脑性瘫痪，涉及运动和协调障碍，不代表人人完全不能移动。Bell’s palsy 是另一个具体病名；看到 palsy，要连同前面的修饰词理解。','cerebral palsy；Bell’s palsy；a person with cerebral palsy。','paralysis 可泛指失去自主运动能力；palsy 常固定在病名中，不能把所有含 palsy 的病名当成同一种疾病。',('The school improved access for a pupil with cerebral palsy.','学校为一名脑性瘫痪学生改善了无障碍设施。'),('The leaflet explains the term Bell’s palsy.','这份说明解释了“贝尔麻痹”这个名称。'),sources=['https://en.wiktionary.org/wiki/palsy#English','https://www.nhs.uk/conditions/cerebral-palsy/']),
E('dialysis','/daɪˈæləsɪs/','透析','借助一层有选择性的膜，把某些小分子和水分分开处理。','借拉丁 dialysis，接希腊 diálusis，dia- 有分开、通过之意，-lysis 接松解、分离。医学用途是在这一分离概念上发展出来的。',L+[['古希腊 dia- + lýsis → diálusis → 拉丁 dialysis','分开、分离'],['英语 dialysis','通过半透膜分离；用于医学透析治疗']],'医疗中的透析帮助排出废物和多余水分，替代一部分肾脏功能；它不是换一套血液，也不等于治好了肾脏。实验室里 dialysis 也可指物质分离方法。','be on dialysis；receive dialysis；a dialysis session；dialysis treatment。','filtration 泛指过滤；dialysis 特指借助半透膜进行的这类分离，不是普通筛子过滤的同义词。',('Her weekly schedule includes regular dialysis sessions.','她每周的安排包括定期透析。'),('The laboratory used dialysis to remove small molecules from the sample.','实验室使用透析法去除样本中的小分子。'),sources=['https://en.wiktionary.org/wiki/dialysis#English','https://www.niddk.nih.gov/health-information/kidney-disease/kidney-failure/hemodialysis']),
E('hydrolysis','英 /haɪˈdrɒləsɪs/；美 /haɪˈdrɑːləsɪs/','水解','水参与反应，把原来连着的化学键断开。','现代科学构词 hydro-“水” + -lysis“分解”；两个成分分别接希腊 hýdōr 和 lýsis。不是古希腊人已经使用今天完整的化学术语。',[['古希腊 hýdōr；lúein → lýsis','水；解开、分解'],['现代科学 hydro- + -lysis → hydrolysis','水参与的断键反应']],'水解时水是反应参与者；把糖搅进水里直到看不见，通常只是溶解，并没有因此变成水解。消化中的一些分解过程就涉及酶促水解。','the hydrolysis of；undergo hydrolysis；enzyme-catalysed hydrolysis。','dissolution 是溶解；hydrolysis 是化学反应。catalysis 说反应被催化，两者关注点不同。',('The experiment measured the rate of hydrolysis.','实验测量了水解反应的速率。'),('Water participates directly in the hydrolysis of an ester.','水直接参与酯的水解反应。'),sources=['https://en.wiktionary.org/wiki/hydrolysis#English','https://goldbook.iupac.org/terms/view/H02902']),
E('lysine','/ˈlaɪsiːn/','赖氨酸','构成蛋白质的氨基酸之一；人体需要从食物中获得。','lys- 接希腊 lýsis“分解”，-ine 是化学物质名后缀。名称与蛋白质分解这一来源相联，不应解释为“它经常催化反应所以叫这个名字”。',L+[['古希腊 lýsis → 科学组合形式 lys-','分解'],['科学命名 lys- + -ine → lysine','赖氨酸，一种可从蛋白质水解产物中取得的氨基酸']],'可以把蛋白质想成由不同积木组成的长链，lysine 是其中一种积木。essential amino acid 的 essential 指人体不能自行合成足够量、需要饮食供应，不是说别的氨基酸不重要。','lysine content；a source of lysine；an essential amino acid。','lysine 是一种分子；lysosome 是细胞里的结构。两词有共同的“分解”来源，但不是一物的长短名称。',('The report lists the lysine content of several foods.','报告列出了几种食物的赖氨酸含量。'),('Lysine is one of the amino acids used to build proteins.','赖氨酸是构成蛋白质的氨基酸之一。'),sources=['https://www.collinsdictionary.com/dictionary/english/lysine','https://www.merriam-webster.com/dictionary/lysine']),
E('lysosome','英 /ˈlaɪsəsəʊm/；美 /ˈlaɪsəsoʊm/','溶酶体','细胞里的分解回收小室，处理老旧部件和某些送进来的材料。','现代生物学命名 lyso-“分解” + -some“体”；前者接希腊 lýsis，后者接 sôma“身体”。这里的 -some 不是 handsome 中表示形容词的同形后缀。',[['古希腊 lýsis；sôma → 科学组合成分 lyso-、-some','分解；身体、结构体'],['现代科学 lyso- + -some → lysosome','含分解酶的细胞器']],'外面有膜围住，里面的酶把较大材料分成较小成分，部分可以重新利用。把它记成回收处理站比只背“溶解的体”更容易懂；它也不是制造蛋白质的工厂。','a lysosome；lysosome function；inside the lysosome。','ribosome 主要参与蛋白质合成；lysosome 主要参与分解处理。二者词尾相像，工作不同。',('The diagram shows a lysosome inside the cell.','图中标出了细胞内的一个溶酶体。'),('Enzymes in the lysosome break down worn-out cell components.','溶酶体中的酶分解老旧的细胞部件。'),sources=['https://www.merriam-webster.com/dictionary/lysosome','https://www.genome.gov/genetics-glossary/Lysosome'])
]
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());family=next(r['family'] for r in m['roots'] if r['id']=='C0694')
shared=set('psychoanalytic electrolyte electrolysis electrolytic'.split())
excluded={k:'按用户最新选词要求暂略：较窄的细胞、化学过程名称或低频派生，当前先保留通用分析词、常见医疗词和基础科学概念。' for k in 'lysis lysosomal lytic proteolysis hydrolytic autolysis cytolysis hydrolyte lysigeny plasmolysis'.split()}
ROOT=[dict(id='C0694',meaning='解开；松解；分解',core='ly-／lysi-／lyt- = loosen：原来连在一起的东西，被解开或分开。',image='analysis 像把纠缠的问题逐项理开；paralysis 则是活动能力失效。科学词里的分解又发展为水解、透析和催化等具体概念。',intro='来源是古希腊 lúein“解开、松开”，并有 lýsis“分解”和 lyt- 等形式。它既进入日常的 analyse，也进入身体功能和现代科学词。词根给的是理解入口，今天的专业含义必须看具体词，不能一律翻译成溶解。',forms='ly-、lysi-、lyt-、lyso- 是同族不同构词形式。analyse／analyze、paralyse／paralyze、catalyse／catalyze 主要体现英美拼写差异。analysis 与 paralysis 的重音均不在第一个音节。',branches=[['把问题分开理解','analysis、analyse、analyze、analyst、analytic、analytical、analytically、analytics、reanalysis、psychoanalytic'],['推动反应与变化','catalysis、catalyst、catalytic、catalyze、catalyse'],['活动能力失效','paralysis、paralyse、paralyze、paralysed、paralyzed、paralytic、palsy'],['分离与基础科学','dialysis、hydrolysis、electrolysis、electrolyte、electrolytic、lysine、lysosome']],contrasts='palsy 与 paralysis 是不同路线进入英语的同源词；analytical 的英语记录早于 analytic，catalytic 又早于 catalyst，别把今天相近的词形自动排成历史先后。催化不等于分解，水解不等于溶解。',practice='用 analyse 说一件需要拆开研究的事，用 catalyst 说一个推动改变的因素，再说明 paralysis 与 decision paralysis 的具体意思怎样不同。',words=[k for k in family if k not in excluded],exclude=excluded,sources=['https://www.etymonline.com/word/analysis','https://www.etymonline.com/word/paralysis','https://www.etymonline.com/word/catalysis'])]
assert {x['word'] for x in W}==set(family)-shared-set(excluded),(set(family)-shared-set(excluded))-{x['word'] for x in W}
assert len(W)==len({x['word'] for x in W})
assert all(x['word'] in m['owned_words'] for x in W)
for x in W:
 assert len(x['examples'])>=2 and len(x['history'])>=2 and x['ipa'],x['word']
 assert all(len(n)==2 and all(isinstance(v,str) and v for v in n) for n in x['history']),x['word']
for k,d in [('roots',ROOT),('words',W)]: (OUT/f'{k}_batch200_spec_53_ly.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print('C0694',len(W),'new',len(ROOT[0]['words']),'references',sum(len(x['examples']) for x in W),'examples')
